import { APISchemaBase, type Attribute, type Prim, type Stage } from 'typescript-usd/usd'

/**
 * UsdShadeMaterialBindingAPI is an API schema that provides an 
 * interface for binding materials to prims or collections of prims 
 * (represented by UsdCollectionAPI objects). 
 *
 * In the USD shading model, each renderable gprim computes a single 
 * <b>resolved Material</b> that will be used to shade the gprim (exceptions, 
 * of course, for gprims that possess UsdGeomSubsets, as each subset can be 
 * shaded by a different Material).  A gprim <b>and each of its ancestor 
 * prims</b> can possess, through the MaterialBindingAPI, both a 
 * <b>direct</b> binding to a Material, and any number of 
 * <b>collection-based</b> bindings to Materials; each binding can be generic 
 * or declared for a particular <b>purpose</b>, and given a specific <b>binding 
 * strength</b>. It is the process of "material resolution" (see 
 * \ref UsdShadeMaterialBindingAPI_MaterialResolution) that examines all of 
 * these bindings, and selects the one Material that best matches the 
 * client's needs.
 *
 * The intent of <b>purpose</b> is that each gprim should be able to resolve a 
 * Material for any given purpose, which implies it can have differently bound 
 * materials for different purposes. There are two <i>special</i> values of 
 * <b>purpose</b> defined in UsdShade, although the API fully supports 
 * specifying arbitrary values for it, for the sake of extensibility:
 * <ul><li><b>UsdShadeTokens->full</b>: to be used when the purpose of the 
 * render is entirely to visualize the truest representation of a scene, 
 * considering all lighting and material information, at highest fidelity.</li>  
 * <li><b>UsdShadeTokens->preview</b>: to be used when the render is in 
 * service of a goal other than a high fidelity "full" render (such as scene
 * manipulation, modeling, or realtime playback). Latency and speed are 
 * generally of greater concern for preview renders, therefore preview 
 * materials are generally designed to be "lighterweight" compared to full
 * materials.</li></ul>
 * A binding can also have no specific purpose at all, in which 
 * case, it is considered to be the fallback or all-purpose binding (denoted 
 * by the empty-valued token <b>UsdShadeTokens->allPurpose</b>). 
 *
 * The <b>purpose</b> of a material binding is encoded in the name of the 
 * binding relationship. 
 * <ul><li>
 * In the case of a direct binding, the <i>allPurpose</i> binding is 
 * represented by the relationship named <b>material:binding</b>. 
 * Special-purpose direct bindings are represented by relationships named
 * <b>material:binding:<i>purpose</i></b>. A direct binding relationship 
 * must have a single target path that points to a <b>UsdShadeMaterial</b>.</li>
 * <li>
 * In the case of a collection-based binding, the <i>allPurpose</i> binding is 
 * represented by a relationship named 
 * <b>material:binding:collection:<i>bindingName</i></b>, where 
 * <b>bindingName</b> establishes an identity for the binding that is unique 
 * on the prim. Attempting to establish two collection bindings of the same 
 * name on the same prim will result in the first binding simply being 
 * overridden. A special-purpose collection-based binding is represented by a 
 * relationship named <b>material:binding:collection:<i>purpose:bindingName</i></b>.
 * A collection-based binding relationship must have exacly two targets, one of 
 * which should be a collection-path (see 
 * ef UsdCollectionAPI::GetCollectionPath()) and the other should point to a
 * <b>UsdShadeMaterial</b>. In the future, we may allow a single collection 
 * binding to target multiple collections, if we can establish a reasonable 
 * round-tripping pattern for applications that only allow a single collection 
 * to be associated with each Material.
 * </li>
 * </ul>
 *
 * <b>Note:</b> Both <b>bindingName</b> and <b>purpose</b> must be 
 * non-namespaced tokens. This allows us to know the role of a binding 
 * relationship simply from the number of tokens in it. 
 * <ul><li><b>Two tokens</b>: the fallback, "all purpose", direct binding, 
 * <i>material:binding</i></li>
 * <li><b>Three tokens</b>: a purpose-restricted, direct, fallback binding, 
 * e.g. material:binding:preview</li>
 * <li><b>Four tokens</b>: an all-purpose, collection-based binding, e.g. 
 * material:binding:collection:metalBits</li>
 * <li><b>Five tokens</b>: a purpose-restricted, collection-based binding, 
 * e.g. material:binding:collection:full:metalBits</li>
 * </ul>
 *
 * A <b>binding-strength</b> value is used to specify whether a binding 
 * authored on a prim should be weaker or stronger than bindings that appear 
 * lower in namespace. We encode the binding strength with as token-valued 
 * metadata <b>'bindMaterialAs'</b> for future flexibility, even though for 
 * now, there are only two possible values:
 * <i>UsdShadeTokens->weakerThanDescendants</i> and 
 * <i>UsdShadeTokens->strongerThanDescendants</i>. When binding-strength is 
 * not authored (i.e. empty) on a binding-relationship, the default behavior 
 * matches UsdShadeTokens->weakerThanDescendants.
 *
 * \note If a material binding relationship is a built-in property defined as 
 * part of a typed prim's schema, a fallback value should not be provided for 
 * it. This is because the "material resolution" algorithm only conisders 
 * <i>authored</i> properties.
 */
export class MaterialBindingAPI extends APISchemaBase {
  static readonly typeName: string = "MaterialBindingAPI"

  static get(stage: Stage, path: string): MaterialBindingAPI {
    return new MaterialBindingAPI(stage.getPrim(path), stage)
  }

  isValid(): boolean {
    return super.isValid() && this.prim.hasAPI(MaterialBindingAPI.typeName)
  }

  static canApply(prim: Prim): boolean {
    return prim.canApplyAPI(MaterialBindingAPI.typeName)
  }
  static apply(prim: Prim): MaterialBindingAPI {
    if (prim.applyAPI(MaterialBindingAPI.typeName)) return new MaterialBindingAPI(prim, prim.getStage())
    return new MaterialBindingAPI(undefined, prim.getStage())
  }

  static getSchemaAttributeNames(includeInherited = true): string[] {
    const names = includeInherited
      ? []
      : []
    return names
  }

  // --(BEGIN CUSTOM CODE)--
  // Authors a direct binding rel on this prim (UsdShadeMaterialBindingAPI::
  // Bind). With a non-empty purpose, authors material:binding:<purpose>.
  bind(
    material: Material | string,
    strength: BindingStrength | 'fallbackStrength' = 'fallbackStrength',
    purpose: string = ALL_PURPOSE,
  ): void {
    const materialPath = typeof material === 'string' ? material : material.path
    const relName = directBindingRelName(purpose)
    this._rel(relName).setTargets([materialPath])
    this._setBindingStrength(relName, strength)
  }

  // Authors a collection-based binding (UsdShadeMaterialBindingAPI::Bind for a
  // UsdCollectionAPI). `collectionPath` is the collection property path
  // (/Prim.collection:<name>); `bindingName` defaults to the collection name.
  bindCollection(
    bindingName: string,
    collectionPath: string,
    material: Material | string,
    strength: BindingStrength | 'fallbackStrength' = 'fallbackStrength',
    purpose: string = ALL_PURPOSE,
  ): void {
    const materialPath = typeof material === 'string' ? material : material.path
    const relName = `${collectionBindingPrefix(purpose)}:${bindingName}`
    // Two targets: collection path first, then the material path
    // (CollectionBinding accepts either order; upstream authors coll, mat).
    this._rel(relName).setTargets([collectionPath, materialPath])
    this._setBindingStrength(relName, strength)
  }

  // OpenUSD v26.11.1 materialBindingAPI.cpp:376-397. Fallback resets an
  // existing stronger opinion while avoiding needless default metadata.
  private _setBindingStrength(relName: string, strength: BindingStrength | 'fallbackStrength'): void {
    const path = `${this.path}.${relName}`
    const previous = this._stage.get(path)?.getField('bindMaterialAs')
    if (strength !== 'fallbackStrength') this._stage.setPropertyField(path, 'bindMaterialAs', strength)
    else if (previous && previous !== 'weakerThanDescendants') this._stage.setPropertyField(path, 'bindMaterialAs', 'weakerThanDescendants')
  }

  unbind(): void {
    this._rel(BINDING_REL_NAME).setTargets([])
  }

  // UsdShadeMaterialBindingAPI::GetDirectBindingRel
  // (OpenUSD 26.11.1 materialBindingAPI.cpp:177-181).
  getDirectBindingRel(materialPurpose: string = ALL_PURPOSE): UsdRel {
    return this._prim.rel(directBindingRelName(materialPurpose))
  }

  // UsdShadeMaterialBindingAPI::UnbindDirectBinding (materialBindingAPI.cpp:
  // 463-470): author an empty, non-custom direct-binding relationship, which
  // blocks any weaker binding opinions.
  unbindDirectBinding(materialPurpose: string = ALL_PURPOSE): boolean {
    const rel = this._prim.createRelationship(directBindingRelName(materialPurpose), /*custom*/ false)
    rel.setTargets([])
    return true
  }

  // UsdShadeMaterialBindingAPI::UnbindCollectionBinding
  // (materialBindingAPI.cpp:472-481).
  unbindCollectionBinding(bindingName: string, materialPurpose: string = ALL_PURPOSE): boolean {
    const rel = this._prim.createRelationship(
      `${collectionBindingPrefix(materialPurpose)}:${bindingName}`, /*custom*/ false)
    rel.setTargets([])
    return true
  }

  // UsdShadeMaterialBindingAPI::UnbindAllBindings (materialBindingAPI.cpp:
  // 483-506): clear the targets of material:binding and every relationship
  // in the material:binding namespace.
  unbindAllBindings(): boolean {
    const names = this._prim.getPropertiesInNamespace(BINDING_REL_NAME)
      .filter(p => p.isRelationship).map(p => p.name)
    if (this._prim.getAttr(BINDING_REL_NAME)?.isRelationship) names.push(BINDING_REL_NAME)
    for (const name of names) this._prim.rel(name).setTargets([])
    return true
  }

  // ---- Material-bind GeomSubsets ----

  // Creates a GeomSubset child of this prim in the "materialBind" family with
  // the given face (default) indices, then ensures the family's familyType is
  // at least "nonOverlapping" (materials bound to subsets must have mutually
  // exclusive index sets). Mirrors UsdShadeMaterialBindingAPI::
  // CreateMaterialBindSubset.
  createMaterialBindSubset(
    subsetName: string,
    indices: number[],
    elementType: ElementType = 'face',
  ): GeomSubset {
    const geomPath = this._prim.path
    const result = GeomSubset.createGeomSubset(
      this._stage, geomPath, subsetName, elementType, indices, MATERIAL_BIND_FAMILY,
    )

    const familyType = GeomSubset.getFamilyType(this._stage, geomPath, MATERIAL_BIND_FAMILY)
    // Subsets with bound materials should have mutually exclusive index sets,
    // so promote an unset/unrestricted family to "nonOverlapping".
    if (familyType === 'unrestricted') {
      this.setMaterialBindSubsetsFamilyType('nonOverlapping')
    }

    return result
  }

  // All GeomSubsets of this prim in the "materialBind" family (any elementType).
  // Mirrors UsdShadeMaterialBindingAPI::GetMaterialBindSubsets.
  getMaterialBindSubsets(): Prim[] {
    return GeomSubset.getGeomSubsets(this._stage, this._prim.path, '', MATERIAL_BIND_FAMILY)
  }

  // The familyType of the "materialBind" family (default 'unrestricted' when
  // unset). Mirrors UsdShadeMaterialBindingAPI::GetMaterialBindSubsetsFamilyType.
  getMaterialBindSubsetsFamilyType(): FamilyType {
    return GeomSubset.getFamilyType(this._stage, this._prim.path, MATERIAL_BIND_FAMILY)
  }

  // Sets the familyType of the "materialBind" family. 'unrestricted' is
  // rejected (subsets with bound materials must be at least non-overlapping).
  // Mirrors UsdShadeMaterialBindingAPI::SetMaterialBindSubsetsFamilyType.
  setMaterialBindSubsetsFamilyType(familyType: FamilyType): boolean {
    if (familyType === 'unrestricted') {
      // TF_CODING_ERROR upstream — refuse and report failure.
      return false
    }
    GeomSubset.setFamilyType(this._stage, this._prim.path, MATERIAL_BIND_FAMILY, familyType)
    return true
  }

  // ---- Reading ----

  // The directly-authored all-purpose binding on this prim (no ancestor
  // resolution). Kept for back-compat with existing callers.
  static getDirectBinding(prim: Prim): string | null {
    const rel = prim.getAttr(BINDING_REL_NAME)
    const targets = rel?.getTargets() ?? []
    return targets.length > 0 ? targets[0]! : null
  }

  static getBindingStrength(stage: Stage, bindingRelPath: string): BindingStrength {
    const field = stage.get(bindingRelPath)?.getField('bindMaterialAs')
    return field === 'strongerThanDescendants' ? 'strongerThanDescendants' : 'weakerThanDescendants'
  }

  // The direct binding for `purpose` authored on `prim`, or null. Returns the
  // rel name and the (single, prim-path) material target
  // (BindingsAtPrim::directBinding for one purpose).
  private static _directBindingForPurpose(
    prim: Prim, purpose: string,
  ): { relName: string; materialPath: string } | null {
    const relName = directBindingRelName(purpose)
    const targets = prim.getAttr(relName)?.getTargets() ?? []
    if (targets.length === 1 && isPrimPath(targets[0]!)) {
      return { relName, materialPath: targets[0]! }
    }
    return null
  }

  // All collection bindings for `purpose` authored on `prim`, in authored
  // order (BindingsAtPrim::{allPurpose,restrictedPurpose}CollBindings). A
  // collection binding has exactly two targets, exactly one of which is a
  // prim path (the material); the other is the collection property path.
  private static _collectionBindingsForPurpose(prim: Prim, purpose: string): CollectionBinding[] {
    const prefix = collectionBindingPrefix(purpose)
    const result: CollectionBinding[] = []
    // attrNames lists every authored property (rels included), in order.
    for (const name of prim.attrNames) {
      if (name === prefix || !name.startsWith(`${prefix}:`)) continue
      // For all-purpose, exclude purpose-qualified coll rels: the segment
      // after the prefix must be the bare binding name (no further ':').
      // (_GetCollectionBindingPropertyNames's "no ':' in the second half".)
      if (purpose === ALL_PURPOSE && name.slice(prefix.length + 1).includes(':')) continue

      const targets = prim.getAttr(name)?.getTargets() ?? []
      if (targets.length !== 2) continue
      const firstIsPrim = isPrimPath(targets[0]!)
      const secondIsPrim = isPrimPath(targets[1]!)
      if (firstIsPrim === secondIsPrim) continue // need exactly one prim path
      const materialPath = firstIsPrim ? targets[0]! : targets[1]!
      const collectionPath = firstIsPrim ? targets[1]! : targets[0]!
      result.push({ relName: name, collectionPath, materialPath })
    }
    return result
  }

  // Resolves the bound material for a prim for the given material purpose,
  // mirroring UsdShadeMaterialBindingAPI::ComputeBoundMaterial(). Considers
  // direct and collection bindings on the prim and its ancestors, applying
  // the binding-strength and collection-vs-direct rules. The first of
  // [purpose, allPurpose] that yields a valid binding wins.
  static computeBoundMaterial(
    stage: Stage,
    primPath: string,
    purpose: string = ALL_PURPOSE,
  ): ResolvedBinding | null {
    const materialPurposes = purpose === ALL_PURPOSE ? [ALL_PURPOSE] : [purpose, ALL_PURPOSE]

    for (const p of materialPurposes) {
      const resolved = MaterialBindingAPI._computeForPurpose(stage, primPath, p)
      if (resolved) return resolved
    }
    return null
  }

  private static _computeForPurpose(
    stage: Stage, primPath: string, purpose: string,
  ): ResolvedBinding | null {
    // Cache membership queries per collection path, as upstream does.
    const queryCache = new Map<string, CollectionMembershipQuery>()

    let winner: ResolvedBinding | null = null
    let winnerOnPrimPath: string | null = null // prim that authored the winner
    let hasValid = false

    // Walk prim -> ancestors up to (not including) the pseudo-root.
    let path: string | null = primPath
    while (path && path !== '/') {
      const prim = stage.getPrim(path)
      if (!prim) { path = parentPath(path); continue }

      // -- Direct binding for this purpose on `prim` --
      const direct = MaterialBindingAPI._directBindingForPurpose(prim, purpose)
      if (direct) {
        const relPath = `${path}.${direct.relName}`
        const strength = MaterialBindingAPI.getBindingStrength(stage, relPath)
        if (!hasValid || strength === 'strongerThanDescendants') {
          hasValid = true
          winner = { materialPath: direct.materialPath, bindingRelPath: relPath }
          winnerOnPrimPath = path
        }
      }

      // -- Collection bindings for this purpose on `prim` --
      const collBindings = MaterialBindingAPI._collectionBindingsForPurpose(prim, purpose)
      for (const cb of collBindings) {
        // Resolve the collection: <collectionPrimPath>.collection:<name>
        const dotIdx = cb.collectionPath.indexOf('.')
        if (dotIdx < 0) continue
        const collPrimPath = cb.collectionPath.slice(0, dotIdx)
        const collProp = cb.collectionPath.slice(dotIdx + 1) // collection:<name>:...
        const m = /^collection:([^:]+)/.exec(collProp)
        if (!m) continue
        const collectionName = m[1]!
        const collPrim = stage.getPrim(collPrimPath)
        if (!collPrim) continue

        let query = queryCache.get(cb.collectionPath)
        if (!query) {
          query = CollectionMembershipQuery.compute(collPrim, collectionName)
          queryCache.set(cb.collectionPath, query)
        }

        if (query.isPathIncluded(primPath)) {
          const relPath = `${path}.${cb.relName}`
          const strength = MaterialBindingAPI.getBindingStrength(stage, relPath)
          // A collection binding wins if there is no winner yet, OR the
          // current winner was authored on THIS prim (collection beats a
          // direct binding on the same prim), OR it is stronger-than-desc.
          if (!hasValid || winnerOnPrimPath === path || strength === 'strongerThanDescendants') {
            hasValid = true
            winner = { materialPath: cb.materialPath, bindingRelPath: relPath }
            winnerOnPrimPath = path
            // The first matching collection binding is the one we keep.
            break
          }
        }
      }

      path = parentPath(path)
    }

    if (!hasValid || !winner) return null
    // Make sure the bound material exists and is a UsdShadeMaterial.
    const materialPrim = stage.getPrim(winner.materialPath)
    if (!materialPrim || !Material.is(materialPrim)) return null
    return winner
  }
}


// UsdShadeMaterialBindingAPI — binds materials to geometry.
// Reference: pxr/usd/usdShade/materialBindingAPI.cpp (ComputeBoundMaterial).
//
// Three flavors of binding, all resolved by ComputeBoundMaterial:
//
//   * Direct binding (all-purpose):
//       rel material:binding = </path/To/Material>
//   * Direct, purpose-qualified binding:
//       rel material:binding:full    = </Mat>
//       rel material:binding:preview = </Mat>
//       rel material:binding:<purpose> = </Mat>     (general purpose)
//   * Collection-based binding (a named binding pointing at a collection +
//     material; two targets [collectionPath, materialPath]):
//       rel material:binding:collection:<name>            = [</P.collection:c>, </Mat>]
//       rel material:binding:collection:<purpose>:<name>  = [</P.collection:c>, </Mat>]
//
// Binding strength is stored as the 'bindMaterialAs' metadata field on the rel
// spec: 'weakerThanDescendants' (default) or 'strongerThanDescendants'.
//
// Resolution (UsdShadeMaterialBindingAPI::ComputeBoundMaterial):
//   materialPurposes = [purpose, allPurpose]  (allPurpose only once)
//   For each purpose, walk the prim then its ancestors up to (not incl.) root.
//   At each prim consider the direct binding for that purpose, then the
//   collection bindings for that purpose. A binding wins when there is no
//   current winner, OR it is strongerThanDescendants, OR — for a collection
//   binding — the current winner was authored on this same prim (collection
//   binding beats a direct binding on the same prim). The first purpose that
//   yields any valid binding wins outright.

import type { Rel as UsdRel } from 'typescript-usd/usd'
import { Subset as GeomSubset, type ElementType, type FamilyType } from 'typescript-usd/usdGeom'
import { Material } from './material.ts'
import { CollectionMembershipQuery } from 'typescript-usd/usd'

export type BindingStrength = 'weakerThanDescendants' | 'strongerThanDescendants'

export const BINDING_REL_NAME = 'material:binding'

// Material purpose tokens (UsdShadeTokens). 'allPurpose' is the empty token
// upstream; we use '' so the [purpose, allPurpose] vector and rel-name joins
// line up with material:binding (no purpose suffix).
export const ALL_PURPOSE = ''
export const PREVIEW_PURPOSE = 'preview'
export const FULL_PURPOSE = 'full'

// The applied API schema name recorded in a prim's apiSchemas listOp.
export const MATERIAL_BINDING_API_SCHEMA_NAME = 'MaterialBindingAPI'

const COLLECTION_PREFIX = 'material:binding:collection'

// The reserved family name for material-bind GeomSubsets (UsdShadeTokens->
// materialBind). All face subsets a material is bound to live in this family.
export const MATERIAL_BIND_FAMILY = 'materialBind'

export interface ResolvedBinding {
  materialPath: string
  bindingRelPath: string   // the rel that won, e.g. '/Root.material:binding'
}

function parentPath(path: string): string | null {
  if (path === '/' || !path.startsWith('/')) return null
  const idx = path.lastIndexOf('/')
  return idx === 0 ? '/' : path.slice(0, idx)
}

// The direct-binding rel name for a purpose (_GetDirectBindingRelName).
function directBindingRelName(purpose: string): string {
  return purpose === ALL_PURPOSE ? BINDING_REL_NAME : `${BINDING_REL_NAME}:${purpose}`
}

// The collection-binding rel-name prefix for a purpose
// (_GetCollectionBindingRelName with an empty bindingName).
function collectionBindingPrefix(purpose: string): string {
  return purpose === ALL_PURPOSE ? COLLECTION_PREFIX : `${COLLECTION_PREFIX}:${purpose}`
}

// A path is a prim path (no '.' separating a property component).
function isPrimPath(path: string): boolean {
  return path.startsWith('/') && !path.includes('.')
}

interface CollectionBinding {
  relName: string
  collectionPath: string  // a property path: /Prim.collection:<name>
  materialPath: string
}
